        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"mock","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","duration_minutes":150,"total_marks":259,"source":"myp-mock-myp5-mock","mock_exam_key":"myp5-mock","mock_code":"MYP5-MOCK-2026","sections":[{"id":"A","title":"Section A — Objective","questions":22,"marks":60,"instructions":"One correct answer per question. The options are written so a wrong choice identifies a specific misconception."},{"id":"B","title":"Section B — Structured","questions":23,"marks":199,"instructions":"Show your working. Every part carries its own marks, its own answer box and its own two hints."}]}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
